private class Env(val parent: Env? = null){
    val frame = mutableMapOf<String, Any>()
    fun find(n: String): Env{
        var e: Env? = this;
        while (e != null){
            if (e.frame.containsKey(n))return e;
            e = e.parent
    fun get(n: String): Any{
        val v = find(n).frame.getValue(n);
        if (v === Uninitialized)error("uninitialized variable: $n");
        return v
